import * as T from './three.module.mjs';
import {SYSTEMS} from './systems.mjs';
import {VIEWS,initialState,isVisible,soloSystem,showAll,chassisOnly,cameraAngles} from './state.mjs';

const $=s=>document.querySelector(s),canvas=$('#scene'),viewport=$('#viewport');
const state=initialState(SYSTEMS),meshes=[],materials=new Set(),pointers=new Map();
let renderer,model,scene,camera,key,shadowPlane,needsRender=true,autoRotate=false,ready=false;
let theta=1.10,phi=1.02,distance=25,groupRadius=9,lastFrame=0;
const target=new T.Vector3(-1.1,1.7,0),systemsById=new Map(SYSTEMS.map(s=>[s[0],s]));
function notifyError(error){$('#loading').classList.add('hidden');$('#error-card').hidden=false;$('#error-message').textContent=error.message||String(error);console.error(error);}
function syncVisibility(){
 if(!ready)return;let visible=0;const counts={};
 for(const o of meshes){o.visible=isVisible(o.userData,state);if(o.visible){visible++;counts[o.userData.system]=(counts[o.userData.system]||0)+1;}o.position.fromArray(o.userData.originalPosition);if(o.userData.assembly==='upper')o.position.y+=state.separation;}
 for(const m of materials)if(m.name==='shell'){m.opacity=state.opacity;m.transparent=state.opacity<1;m.depthWrite=state.opacity===1;m.needsUpdate=true;}
 $('#visible-count').textContent=visible.toLocaleString('zh-CN');
 for(const[id]of SYSTEMS){const row=$(`[data-system="${id}"]`);row.querySelector('input').checked=state.visible[id];row.querySelector('output').textContent=counts[id]||0;}
 $('#view-status').textContent=visible===0?'当前没有可见部件，请打开部件显示开关。':'';
 $('#level-summary').textContent=['基础轮廓','结构组件','完整细节'][state.detail];$('#opacity-value').textContent=Math.round(state.opacity*100)+'%';$('#separation-value').textContent=Math.round(state.separation*100)+' cm';$('#cutaway').checked=state.cutaway;
 viewport.dataset.visibleCount=String(visible);viewport.dataset.level=state.detail;needsRender=true;
}
function updateCamera(){if(!camera)return;const aspect=Math.max(.1,camera.aspect),halfV=T.MathUtils.degToRad(camera.fov/2),halfH=Math.atan(Math.tan(halfV)*aspect);const fit=groupRadius/Math.sin(Math.min(halfH,halfV))*1.1;const d=distance*Math.max(1,fit/(groupRadius*3.05));camera.position.set(target.x+d*Math.sin(phi)*Math.cos(theta),target.y+d*Math.cos(phi),target.z+d*Math.sin(phi)*Math.sin(theta));camera.lookAt(target);if(shadowPlane)shadowPlane.visible=$('#shadow').checked&&camera.position.y>0;needsRender=true;}
function resize(){if(!renderer)return;const r=viewport.getBoundingClientRect();renderer.setSize(Math.max(1,r.width),Math.max(1,r.height),false);camera.aspect=r.width/Math.max(1,r.height);camera.updateProjectionMatrix();updateCamera();}
function focusView(id){const p=VIEWS[id];if(!p||!ready)return;state.view=id;target.fromArray(p.target);theta=p.theta;phi=p.phi;distance=p.distance;groupRadius=p.distance/3.05;$('#view-title').textContent=p.title;$('#eyebrow').textContent='TRAILER / '+id.toUpperCase();$('#view-description').textContent=systemsById.get(id)?.[2]||'白色外观 · 蓝色机械结构';$('#focus-view').value=id;document.querySelectorAll('[data-camera]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.camera==='iso')));updateCamera();}
function isolate(id){if(!systemsById.has(id)||!ready)return;soloSystem(state,id);syncVisibility();focusView(id);closeDrawers();}
function reset(){if(!ready)return;showAll(state);state.detail=2;state.opacity=.48;state.separation=0;autoRotate=false;$('#auto-rotate').setAttribute('aria-pressed','false');$('#detail-level').value='2';$('#shell-opacity').value='48';$('#coupling-separation').value='0';describeDetail();syncVisibility();focusView('overview');closeDrawers();}
function describeDetail(){$('#detail-description').textContent=['仅保留主要承载件、壳体和轮组。','增加支架、管路、连杆和锁止机构。','显示螺栓、焊缝、传感线和丝杠螺纹。'][state.detail];}
function prepareUI(){const tree=$('#model-tree');for(const[id,label,desc]of SYSTEMS){const row=document.createElement('div');row.className='system-row';row.dataset.system=id;const control=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=true;input.setAttribute('aria-label','显示'+label);const text=document.createElement('span');text.textContent=label;const count=document.createElement('output');count.setAttribute('aria-label',label+'可见部件数');control.append(input,text,count);control.title=desc;const solo=document.createElement('button');solo.type='button';solo.textContent='单独';solo.setAttribute('aria-label','单独展示'+label);solo.addEventListener('click',()=>isolate(id));input.addEventListener('change',()=>{state.visible[id]=input.checked;syncVisibility();});row.append(control,solo);tree.append(row);}for(const[id,p]of Object.entries(VIEWS)){const option=document.createElement('option');option.value=id;option.textContent=p.title;$('#focus-view').append(option);}}
function pan(dx,dy){const scale=distance*.0013,right=new T.Vector3().setFromMatrixColumn(camera.matrixWorld,0),up=new T.Vector3().setFromMatrixColumn(camera.matrixWorld,1);target.addScaledVector(right,-dx*scale).addScaledVector(up,dy*scale);}
function closeDrawers(){document.body.classList.remove('show-systems','show-settings');$('#drawer-scrim').hidden=true;}
function openDrawer(kind){closeDrawers();document.body.classList.add('show-'+kind);$('#drawer-scrim').hidden=false;}

prepareUI();
$('#focus-view').addEventListener('change',e=>focusView(e.target.value));$('#solo-focus').addEventListener('click',()=>state.view==='overview'?reset():isolate(state.view));$('#toggle-all').addEventListener('click',()=>{showAll(state);syncVisibility();});$('#chassis-only').addEventListener('click',()=>{chassisOnly(state);syncVisibility();focusView('frame');closeDrawers();});
$('#detail-level').addEventListener('change',e=>{state.detail=Number(e.target.value);describeDetail();syncVisibility();});$('#shell-opacity').addEventListener('input',e=>{state.opacity=Number(e.target.value)/100;syncVisibility();});$('#coupling-separation').addEventListener('input',e=>{state.separation=Number(e.target.value)/100;syncVisibility();});$('#cutaway').addEventListener('change',e=>{state.cutaway=e.target.checked;syncVisibility();});$('#shadow').addEventListener('change',()=>{if(renderer)renderer.shadowMap.enabled=$('#shadow').checked;updateCamera();});
$('#reset').onclick=reset;$('#mobile-reset').onclick=reset;$('#retry').onclick=()=>location.reload();$('#auto-rotate').onclick=e=>{autoRotate=!autoRotate;e.currentTarget.setAttribute('aria-pressed',String(autoRotate));};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('#view-status').textContent='此浏览器暂不支持全屏，可手动放大窗口。';}};
$('#open-systems').onclick=()=>openDrawer('systems');$('#open-settings').onclick=()=>openDrawer('settings');$('#drawer-scrim').onclick=closeDrawers;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeDrawers);document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{[theta,phi]=cameraAngles(b.dataset.camera);document.querySelectorAll('[data-camera]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));updateCamera();});
canvas.addEventListener('pointerdown',e=>{if(!ready)return;canvas.focus({preventScroll:true});pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,button:e.button});canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!ready)return;const old=pointers.get(e.pointerId),next={x:e.clientX,y:e.clientY,button:old.button};if(pointers.size===2){const other=[...pointers.entries()].find(([id])=>id!==e.pointerId)[1],before=Math.hypot(old.x-other.x,old.y-other.y),after=Math.hypot(next.x-other.x,next.y-other.y);if(before>0&&after>0)distance=Math.max(.65,Math.min(100,distance*before/after));pan((next.x-old.x)/2,(next.y-old.y)/2);}else if(old.button===2||e.shiftKey)pan(next.x-old.x,next.y-old.y);else{theta-=(next.x-old.x)*.006;phi=T.MathUtils.clamp(phi+(next.y-old.y)*.006,.001,Math.PI-.001);}pointers.set(e.pointerId,next);updateCamera();});
for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>pointers.delete(e.pointerId));canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{e.preventDefault();distance=T.MathUtils.clamp(distance*Math.exp(e.deltaY*.001),.65,100);updateCamera();},{passive:false});
canvas.addEventListener('keydown',e=>{const map={ArrowLeft:[-.10,0],ArrowRight:[.10,0],ArrowUp:[0,-.10],ArrowDown:[0,.10]};if(map[e.key]){e.preventDefault();theta+=map[e.key][0];phi=T.MathUtils.clamp(phi+map[e.key][1],.001,Math.PI-.001);}else if(e.key==='+'||e.key==='=')distance*=.9;else if(e.key==='-')distance*=1.1;else if(e.key==='0')return reset();else return;updateCamera();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawers();});window.addEventListener('resize',resize);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();notifyError(new Error('图形上下文中断，请重新加载模型。'));});

async function init(){try{
renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;scene=new T.Scene();camera=new T.PerspectiveCamera(34,1,.01,350);scene.add(new T.HemisphereLight(0xffffff,0x49658e,1.65));key=new T.DirectionalLight(0xffffff,2.45);key.position.set(2,14,8);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.bias=-.0003;Object.assign(key.shadow.camera,{left:-15,right:15,top:12,bottom:-12,near:.1,far:50});scene.add(key);const fill=new T.DirectionalLight(0xb8d0ff,1.35);fill.position.set(-8,7,-10);scene.add(fill);shadowPlane=new T.Mesh(new T.PlaneGeometry(100,100),new T.ShadowMaterial({opacity:.25}));shadowPlane.rotation.x=-Math.PI/2;shadowPlane.position.y=-.008;shadowPlane.receiveShadow=true;scene.add(shadowPlane);
const {build}=await import('./systems.mjs');model=build();model.traverse(o=>{if(!o.isMesh)return;o.userData.shell=o.material.name==='shell';o.userData.cutawayHide=/Cab body|Sculpted roof|Roof hatch|Roof raised|Interior overhead|Interior dome|Interior sun visor|Cab rear aerodynamic/.test(o.name);meshes.push(o);materials.add(o.material);});scene.add(model);ready=true;$('#part-count').textContent=meshes.length.toLocaleString('zh-CN');resize();syncVisibility();focusView('overview');$('#loading').classList.add('hidden');
const context=document.modelContext;
if(context?.registerTool){try{await context.registerTool({name:'inspect_trailer_system',description:'聚焦并单独显示一个车辆系统。',annotations:{readOnlyHint:false,untrustedContentHint:false},inputSchema:{type:'object',properties:{system:{type:'string',enum:SYSTEMS.map(s=>s[0])}},required:['system'],additionalProperties:false},execute:async(input)=>{if(!input||!systemsById.has(input.system))throw new Error('未知系统');isolate(input.system);return {system:input.system,visible:meshes.filter(o=>o.visible).length};}});}catch(error){console.warn('可选结构化控制不可用',error);}}
function frame(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;if(autoRotate&&!pointers.size){theta-=dt*.20;updateCamera();}if(needsRender){renderer.render(scene,camera);needsRender=false;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
}catch(e){notifyError(e);}}
requestAnimationFrame(()=>requestAnimationFrame(init));
